  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00252",
          "explanation": "The doctor explained source control in accessible terms rather than portraying drainage as arbitrary surgery.",
          "quote": "如果已经有脓，光靠消炎药不一定进得去"
        },
        {
          "event_id": "lite_evt_00252",
          "explanation": "The doctor reduced anesthesia fear without promising that general anesthesia would or would not be used.",
          "quote": "不是听到引流就一定全麻。"
        }
      ],
      "completion": "complete",
      "explanation": "HO1 was triggered by fear of cutting/drainage and anesthesia; the doctor repeatedly explained drainage as source control, emphasized that the decision depends on CT/exam/operative assessment, and supplied language to help the family persuade the patient without overpromising.",
